import numpy as np
import pandas as pd
import xgboost as xgb

x5 = np.array([1, 2, 3, 4, 5], dtype=float)
y5 = np.array([2, 4, 9, 10, 15], dtype=float)

def mejor_tocon(x, r):
    """Tocón de regresión: corte que minimiza la suma de cuadrados de los residuos."""
    mejor = None
    for k in range(1, len(x)):
        izq, der = r[:k], r[k:]
        sse = ((izq - izq.mean()) ** 2).sum() + ((der - der.mean()) ** 2).sum()
        if mejor is None or sse < mejor[0]:
            mejor = (sse, (x[k - 1] + x[k]) / 2, izq.mean(), der.mean())
    return mejor[1:]

F, eta, filas = np.full(5, y5.mean()), 0.5, []
filas.append({"ronda": 0, "predicciones": np.round(F, 2), "corte": None, "SSE": ((y5 - F) ** 2).sum()})
for m in range(1, 4):
    corte, a, b = mejor_tocon(x5, y5 - F)
    F = F + eta * np.where(x5 <= corte, a, b)
    filas.append({"ronda": m, "predicciones": np.round(F, 2), "corte": corte, "SSE": round(((y5 - F) ** 2).sum(), 2)})
print(pd.DataFrame(filas).to_string(index=False))

# Primera ronda de XGBoost con λ = 1: pesos de hoja −G/(H+λ)
m1 = xgb.XGBRegressor(n_estimators=1, max_depth=1, learning_rate=1.0, reg_lambda=1.0, base_score=8.0,
                      tree_method="exact", min_child_weight=0).fit(x5.reshape(-1, 1), y5)
print(m1.get_booster().get_dump(with_stats=True)[0])
