    const M = +$('#gb-m').value, eta = +$('#gb-eta').value, maxD = +$('#gb-d').value, lam = +$('#gb-l').value;
    $('#gb-m-v').textContent = M; $('#gb-eta-v').textContent = K.fmt(eta, 2); $('#gb-d-v').textContent = maxD; $('#gb-l-v').textContent = K.fmt(lam, 1);
    const R = boost(eta, maxD, lam);
    const FM = x => { let s = R.F0; for (let m = 0; m < M; m++) s += eta * pred(R.trees[m], x); return s; };
    $('#gb-tr').textContent = K.fmt(R.tr[M], 3); $('#gb-te').textContent = K.fmt(R.te[M], 3);
    const bestM = R.te.indexOf(Math.min(...R.te));
    $('#gb-best').textContent = `${bestM} (${K.fmt(R.te[bestM], 3)})`;
    const c = K.chart($('#gb-svg'), { width: 380, height: 260, x: [0, 10], y: [-3, 6], margin: { left: 40, bottom: 40 } });
    c.axes({ xTicks: 5, yTicks: 5, xLabel: 'x', yLabel: 'y', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 0) });
    c.path(GRID.map(x => [x, freal(x)]), 's3 line dash');
    TR.forEach(p => c.dot(p[0], p[1], 3.5, 's1 dot'));
    c.path(GRID.map(x => [x, FM(x)]), 's2 line');
    const res = TR.map(p => [p[0], p[1] - FM(p[0])]), nxt = R.trees[M];
    const rmax = Math.max(1.5, ...res.map(r => Math.abs(r[1]))) * 1.1;
    const cr = K.chart($('#gb-res'), { width: 380, height: 260, x: [0, 10], y: [-rmax, rmax], margin: { left: 40, bottom: 40 } });
    cr.axes({ xTicks: 5, yTicks: 4, xLabel: 'x', yLabel: 'residuo', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 1) });
    cr.zeroLines();
    res.forEach(r => cr.dot(r[0], r[1], 3.5, 's4 dot'));
    cr.path(GRID.map(x => [x, pred(nxt, x)]), 's5 line');
    const ymax = Math.max(1.6, R.te[0] * 1.05);
    const cc = K.chart($('#gb-curve'), { width: 640, height: 220, x: [0, MMAX], y: [0, ymax], margin: { left: 44, bottom: 40 } });
    cc.axes({ xTicks: 6, yTicks: 4, xLabel: 'rondas M', yLabel: 'ECM', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 1) });
    cc.line(0, 0.36, MMAX, 0.36, 's3 line dash thin');
    cc.path(R.tr.map((v, m) => [m, v]), 's1 line'); cc.path(R.te.map((v, m) => [m, v]), 's4 line');
    cc.dot(M, R.te[M], 6, 's2 dot');
    const note = $('#gb-note');
    if (M === 0) { note.className = 'plab-note warn'; note.textContent = `Con M = 0 el modelo es la constante F₀ = ${K.fmt(R.F0, 2)} (el promedio). El árbol rojo es la primera corrección.`; }
    else if (M > bestM + 40 && R.te[M] > R.te[bestM] + 0.02) { note.className = 'plab-note warn'; note.textContent = `Sobreajuste: el error de entrenamiento sigue bajando (${K.fmt(R.tr[M], 3)}) pero el de prueba subió de ${K.fmt(R.te[bestM], 3)} (ronda ${bestM}) a ${K.fmt(R.te[M], 3)}. En la práctica se detiene con un conjunto de validación (early stopping).`; }
    else { note.className = 'plab-note good'; note.textContent = `Ronda ${M}: ECM de entrenamiento ${K.fmt(R.tr[M], 3)} y de prueba ${K.fmt(R.te[M], 3)}. Con η = ${K.fmt(eta, 2)} el mínimo de prueba está en la ronda ${bestM}; un η menor necesita más rondas pero suele llegar a un mínimo igual o mejor.`; }
  }
  root.querySelectorAll('input[type=range]').forEach(el => el.addEventListener('input', render));
  render();
})();
</script>
